// CRÉATEUR DE LANDING PAGES — parcours COMPLET sur un serveur Next de production local branché sur le FAUX Supabase (multi-entreprises).
// Création → formulaire → aperçu → publication locale → test du lien → copie → soumission du formulaire → attribution de la campagne.
// Deux exemples : « Omra Ramadan 2027 » et « Voyage organisé Turquie ». Ces essais sont SIMULÉS : ils ne prouvent rien sur la production.
//   npm run build && bash tests/e2e/run-creator.sh
import { createRequire } from "node:module"
import { mkdirSync } from "node:fs"
import { createFakeSupabase, ADMIN, AGENT, BOB } from "./fake-supabase.mjs"
const { chromium } = createRequire(import.meta.url)("playwright")

const BASE = process.argv[2] || "http://localhost:3458"
const fake = createFakeSupabase({ multi: true })
await fake.listen(54321)
const db = fake.db
const E2B = fake.E2B_ORG
const SHOTS = new URL("../../docs/captures-createur/", import.meta.url).pathname
mkdirSync(SHOTS, { recursive: true })
let failed = 0
const check = (label, ok, extra = "") => {
  console.log(`${ok ? "✓" : "✗"} ${label}${ok || !extra ? "" : ` — ${extra}`}`)
  if (!ok) failed++
}
const browser = await chromium.launch()
const errors = []
let ip = 0
async function login(email, password, opts = {}) {
  const ctx = await browser.newContext({ viewport: opts.viewport ?? { width: 1366, height: 900 }, locale: "fr-FR", extraHTTPHeaders: { "x-forwarded-for": `10.88.0.${++ip}` } })
  await ctx.grantPermissions(["clipboard-read", "clipboard-write"], { origin: BASE })
  const page = await ctx.newPage()
  page.on("pageerror", (e) => errors.push(e.message))
  await page.goto(`${BASE}/admin/login`)
  await page.fill("input[name=email]", email)
  await page.fill("input[name=password]", password)
  await Promise.all([page.waitForURL((u) => !u.pathname.endsWith("/login"), { timeout: 20000 }), page.click("button[type=submit]")])
  return { ctx, page }
}
const shot = (page, name, full = true) => page.screenshot({ path: `${SHOTS}${name}.jpg`, type: "jpeg", quality: 72, fullPage: full })
const futureDate = (days) => new Date(Date.now() + days * 86400_000).toISOString().slice(0, 10)
const cats = () => db.landing_categories.filter((c) => c.organization_id === E2B)
const leads = () => db.landing_leads.filter((l) => l.organization_id === E2B)

